import{_ as t,o as a,c as r,a2 as o}from"./chunks/framework.DDY-poMm.js";const u=JSON.parse('{"title":"Security","description":"","frontmatter":{},"headers":[],"relativePath":"wallet/security.md","filePath":"wallet/security.md","lastUpdated":1793861180000}'),s={name:"wallet/security.md"};function n(i,e,d,c,l,p){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="security" tabindex="-1">Security <a class="header-anchor" href="#security" aria-label="Permalink to &quot;Security&quot;">​</a></h1><h2 id="self-custody-the-platform-never-touches-private-keys" tabindex="-1">Self-custody; the platform never touches private keys <a class="header-anchor" href="#self-custody-the-platform-never-touches-private-keys" aria-label="Permalink to &quot;Self-custody; the platform never touches private keys&quot;">​</a></h2><p>The recovery phrase is stored only on the user&#39;s phone and encrypted by the device&#39;s secure chip; no private key exists on our servers. Face ID is supported, and repeated wrong passcodes trigger progressively longer lockouts. One app can manage several wallets and import existing private keys.</p><h2 id="tamper-protection" tabindex="-1">Tamper protection <a class="header-anchor" href="#tamper-protection" aria-label="Permalink to &quot;Tamper protection&quot;">​</a></h2><p>Designed so that even if the code is fully understood, no one can steal funds: the app code is obfuscated; rooted / jailbroken devices, debuggers and hooking tools are detected, and the recovery phrase cannot be viewed nor transactions signed in a compromised environment. The trading allowlist is signed offline by the platform and verified with a public key built into the app, so even a compromised server cannot swap the transaction target. On Android, hardware key attestation helps identify modified, unofficial builds, and new versions can be downloaded inside the app and are verified for integrity before installation.</p><h2 id="safety-notes" tabindex="-1">Safety notes <a class="header-anchor" href="#safety-notes" aria-label="Permalink to &quot;Safety notes&quot;">​</a></h2><ul><li>The platform does not store private keys. <strong>A lost recovery phrase cannot be recovered</strong>, so keep an offline backup.</li><li>Tokenized stocks are issued by the issuer. Holders have no shareholder voting rights, and the issuer may pause transfers in certain cases.</li><li>Confirmed on-chain transactions cannot be reversed.</li><li>Predictions can lose money; cross-chain deposits and withdrawals are handled by Polymarket&#39;s official bridge, and confirmed on-chain transfers cannot be reversed.</li></ul>',7)])])}const f=t(s,[["render",n]]);export{u as __pageData,f as default};
